const SidebarManager={init(){this.sidebar=document.getElementById('sidebar');this.toggleBtn=document.getElementById('sidebarToggle');this.overlay=document.getElementById('sidebarOverlay');if(!this.sidebar||!this.toggleBtn)return;if(!this.overlay){this.createOverlay();}
this.bindEvents();},createOverlay(){this.overlay=document.createElement('div');this.overlay.className='sidebar-overlay';this.overlay.id='sidebarOverlay';document.body.appendChild(this.overlay);},bindEvents(){this.toggleBtn.addEventListener('click',()=>this.toggle());this.overlay.addEventListener('click',()=>this.close());const chapterLinks=this.sidebar.querySelectorAll('.chapter-item');chapterLinks.forEach(link=>{link.addEventListener('click',()=>{if(window.innerWidth<992){this.close();}});});window.addEventListener('resize',()=>{if(window.innerWidth>=992){this.sidebar.classList.remove('show');this.overlay.classList.remove('show');}});},toggle(){this.sidebar.classList.toggle('show');this.overlay.classList.toggle('show');},close(){this.sidebar.classList.remove('show');this.overlay.classList.remove('show');},open(){this.sidebar.classList.add('show');this.overlay.classList.add('show');}};if(typeof module!=='undefined'&&module.exports){module.exports=SidebarManager;}
if(typeof window!=='undefined'){if(document.readyState==='loading'){document.addEventListener('DOMContentLoaded',()=>SidebarManager.init());}else{SidebarManager.init();}
window.SidebarManager=SidebarManager;}
